"""Optional reviewed metadata overlay; checkout definitions remain authoritative."""
from copy import deepcopy
from datetime import datetime
import json
from pathlib import Path
import re
from urllib.parse import urlsplit


def _text(value, limit=1000):
    if not isinstance(value, str) or not value.strip() or len(value) > limit:
        raise ValueError("Invalid metadata text")
    if any(ord(c) < 32 or ord(c) == 127 for c in value):
        raise ValueError("Invalid metadata text")
    return value.strip()


def _identity(value):
    if not isinstance(value, str) or not re.fullmatch(r"[0-9a-fA-F]{32}", value):
        raise ValueError("Invalid metadata identity")
    return value.lower()


def _timestamp(value):
    parsed = datetime.fromisoformat(_text(value, 100))
    if parsed.tzinfo is None:
        raise ValueError("Metadata timestamp requires timezone")


def validate_metadata(data, expected_ids):
    if not isinstance(data, dict) or type(data.get("schema_version")) is not int or data["schema_version"] != 1:
        raise ValueError("Unsupported metadata schema")
    if data.get("review_status") != "approved":
        raise ValueError("Metadata is not approved")
    _timestamp(data.get("fetched_at_utc"))
    _timestamp(data.get("reviewed_at_utc"))
    source = data.get("source")
    if not isinstance(source, dict) or source.get("system") != "ServiceNow" or source.get("table") != "cmdb_ci_business_app":
        raise ValueError("Invalid metadata source")
    origin = urlsplit(_text(source.get("origin"), 2048))
    if (origin.scheme != "https" or not origin.hostname or origin.username is not None
            or origin.password is not None or origin.path not in ("", "/") or origin.query or origin.fragment):
        raise ValueError("Invalid metadata origin")
    expected = set(expected_ids)
    if not expected or len(expected) != len(expected_ids):
        raise ValueError("Invalid configured inventory")
    if any(not isinstance(item, str) or not re.fullmatch(r"APP[0-9]{8}", item) for item in expected):
        raise ValueError("Invalid application ID")
    if data.get("scope") != {"kind": "configured_app_ids", "expected_ids": sorted(expected)}:
        raise ValueError("Metadata inventory mismatch")
    records = data.get("applications")
    if not isinstance(records, list) or len(records) != len(expected):
        raise ValueError("Incomplete metadata")
    result, identities, groups = {}, set(), {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {"app_id", "source_sys_id", "official_name", "support_group"}:
            raise ValueError("Unexpected metadata fields")
        app_id = record["app_id"]
        if not isinstance(app_id, str) or app_id not in expected or app_id in result:
            raise ValueError("Unexpected or duplicate application")
        identity = _identity(record["source_sys_id"])
        if identity in identities:
            raise ValueError("Duplicate source identity")
        group = record["support_group"]
        if not isinstance(group, dict) or set(group) != {"sys_id", "name", "email"}:
            raise ValueError("Invalid support group")
        group = {"sys_id": _identity(group["sys_id"]), "name": _text(group["name"]), "email": _text(group["email"])}
        if group["sys_id"] in groups and groups[group["sys_id"]] != group:
            raise ValueError("Inconsistent support group")
        identities.add(identity)
        groups[group["sys_id"]] = group
        result[app_id] = {"source_sys_id": identity, "official_name": _text(record["official_name"]), "support_group": group}
    if set(result) != expected:
        raise ValueError("Missing application metadata")
    return result


def apply_metadata(apps, path):
    """Return copied apps plus a safe status; never partially apply bad metadata."""
    baseline = deepcopy(apps)
    try:
        path = Path(path)
        with path.open("rb") as stream:
            raw = stream.read(5_000_001)
        if len(raw) > 5_000_000:
            raise ValueError("Metadata file too large")
        data = json.loads(raw.decode("utf-8-sig"))
        metadata = validate_metadata(data, [app["app_id"] for app in apps])
        updated = deepcopy(apps)
        for app in updated:
            item = metadata[app["app_id"]]
            app["name"] = item["official_name"]
            app["support_group"] = deepcopy(item["support_group"])
            app["metadata_source_sys_id"] = item["source_sys_id"]
        return updated, "AYS metadata: Loaded"
    except FileNotFoundError:
        return baseline, "AYS metadata: Not installed; using application definitions"
    except (OSError, ValueError, TypeError, KeyError, RecursionError):
        return baseline, "AYS metadata: Rejected; using application definitions"
